package com.example.starter.translation.service;

import com.example.starter.translation.api.ApiException;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * 引文锚点纯规则：引用标识规范化、字符区间校验、交叉检测、
 * 引用文本保留与旧锚点到新锚点的一一映射校验。
 * 区间一律采用左闭右开、按 Java UTF-16 代码单元（字符偏移）计算。
 */
public final class AnchorSupport {

    private AnchorSupport() {
    }

    /** 锚点区间：左闭右开 [start, end)。 */
    public record Range(int start, int end) {
        public int length() {
            return end - start;
        }
    }

    /** 迁移映射：旧锚点 ID 到新锚点区间；引用标识在迁移中保持不变。 */
    public record Migration(long oldAnchorId, Range newRange) {
    }

    /** 规范化引用标识：去首尾空白、转小写（语言无关）；空标识非法。 */
    public static String normalizeCitationKey(String citationKey) {
        if (citationKey == null) {
            throw ApiException.unprocessable("引用标识不能为空");
        }
        String normalized = citationKey.trim().toLowerCase(Locale.ROOT);
        if (normalized.isEmpty()) {
            throw ApiException.unprocessable("引用标识不能为空");
        }
        return normalized;
    }

    /** 校验单个区间：start 非负、end 不越界、长度为正。返回可读问题，合法返回 null。 */
    public static String validateRange(int start, int end, int contentLength) {
        if (start < 0) {
            return "区间起点不能为负数: " + start;
        }
        if (end > contentLength) {
            return "区间终点 " + end + " 超出当前已批准译文长度 " + contentLength;
        }
        if (start >= end) {
            return "区间必须非空且左闭右开: [" + start + ", " + end + ")";
        }
        return null;
    }

    /** 校验同段落一批新区间互不交叉（端点相接允许）；违规时抛出 422。 */
    public static void assertNoOverlap(List<Range> ranges) {
        List<Range> sorted = new ArrayList<>(ranges);
        sorted.sort((a, b) -> a.start() == b.start() ? Integer.compare(a.end(), b.end())
                : Integer.compare(a.start(), b.start()));
        for (int i = 1; i < sorted.size(); i++) {
            Range previous = sorted.get(i - 1);
            Range current = sorted.get(i);
            if (current.start() < previous.end()) {
                throw ApiException.unprocessable("引文锚点区间交叉: [" + previous.start() + ", "
                        + previous.end() + ") 与 [" + current.start() + ", " + current.end() + ")");
            }
        }
    }

    /** 截取区间内文本（左闭右开）。 */
    public static String slice(String content, int start, int end) {
        return content.substring(start, end);
    }

    /**
     * 校验译文修订后全部旧锚点的引用文本被保留。
     *
     * @param oldContent 旧已批准译文
     * @param newContent 新译文
     * @param oldRanges  旧锚点区间（按锚点 ID 顺序）
     * @param mappings   旧锚点到新区间的一一映射；区间未变时映射可省略，但映射存在时必须文本一致
     */
    public static void assertCitationsPreserved(String oldContent, String newContent,
                                                List<Range> oldRanges, List<Migration> mappings) {
        if (oldRanges.isEmpty()) {
            if (mappings != null && !mappings.isEmpty()) {
                throw ApiException.unprocessable("该段落无引文锚点，不能提供锚点映射");
            }
            return;
        }
        // 映射覆盖的旧锚点（区间发生变动的锚点必须显式提供）；未覆盖则沿用旧区间。
        java.util.Map<Long, Range> mapped = new java.util.LinkedHashMap<>();
        Set<Long> duplicated = new HashSet<>();
        for (Migration migration : mappings == null ? List.<Migration>of() : mappings) {
            Range removed = mapped.put(migration.oldAnchorId(), migration.newRange());
            if (removed != null || duplicated.contains(migration.oldAnchorId())) {
                throw ApiException.unprocessable("锚点映射重复: anchorId=" + migration.oldAnchorId());
            }
            duplicated.add(migration.oldAnchorId());
        }
        for (int i = 0; i < oldRanges.size(); i++) {
            Range oldRange = oldRanges.get(i);
            String expected = slice(oldContent, oldRange.start(), oldRange.end());
            Range target = mapped.get((long) i);
            if (target == null) {
                target = oldRange;
            }
            String problem = validateRange(target.start(), target.end(), newContent.length());
            if (problem != null) {
                throw ApiException.unprocessable("锚点 " + i + " 的新" + problem);
            }
            String actual = slice(newContent, target.start(), target.end());
            if (!actual.equals(expected)) {
                throw ApiException.unprocessable("锚点 " + i + " 引用文本不一致：要求保留 \"" + expected
                        + "\"，新区间 [" + target.start() + ", " + target.end() + ") 实际为 \"" + actual + "\"");
            }
        }
        // 映射只能针对现存旧锚点
        for (Long anchorId : mapped.keySet()) {
            if (anchorId < 0 || anchorId >= oldRanges.size()) {
                throw ApiException.unprocessable("锚点映射指向不存在的旧锚点: anchorId=" + anchorId);
            }
        }
    }

    /** 时间截断到微秒，保证 TIMESTAMP(6) 存储与比较精度稳定。 */
    public static Instant truncateToMicros(Instant instant) {
        return Instant.ofEpochSecond(instant.getEpochSecond(), (instant.getNano() / 1000) * 1000);
    }
}

