 * 单条译文提交的锚点保护：存在生效锚点时新译文必须在原区间逐字保留引用文本
 * （区间需移动时必须走批量修订接口并提供映射）；通过后把锚点绑定到新译文版本。
 */
public void preserveOnSubmit(long documentId, String segmentId, String language,
                             String oldContent, String newContent, int newTranslationVersion) {
    List<CitationAnchorRow> active =
            repository.listActiveAnchorsForTranslation(documentId, segmentId, language);
    if (active.isEmpty()) {
        return;
    }
    List<AnchorSupport.OldAnchor> oldAnchors = active.stream()
            .map(a -> new AnchorSupport.OldAnchor(a.citationKey(), a.startOffset(), a.endOffset())).toList();
    try {
        AnchorSupport.resolveAndAssert(oldContent, newContent, oldAnchors, List.of());
    } catch (ApiException e) {
        throw ApiException.unprocessable(e.getMessage()
                + "；区间发生变动时须使用批量修订接口提交旧锚点到新锚点的一一映射");
    }
    for (CitationAnchorRow anchor : active) {
        repository.updateAnchorMigration(anchor.anchorId(), anchor.startOffset(), anchor.endOffset(),
                newTranslationVersion);
    }
}

